def _validate_region_delta_rank_multi_result(
    result: Any, *, where: str = "result"
) -> tuple:
    """Validate a complete :func:`rank_region_delta_multi` result.

    Returns the ``reference``, ``scenarios``, ``elements`` and
    ``regions`` axes and the flat scenario-then-element-then-region
    ``data`` row list.  Each ``both`` row must carry a non-bool int
    ``rank`` and finite non-bool numbers ``magnitude`` and
    ``uncertainty`` (the latter non-negative); every other state must
    carry ``None`` for all three.
    """
    if not isinstance(result, dict):
        raise TypeError(f"{where} must be a dict")
    if tuple(result.keys()) != _REGION_DELTA_RANK_MULTI_OUTPUT_KEYS:
        raise ValueError(
            f"{where} must have exactly the keys schema, reference, "
            "scenarios, elements, regions, data in order"
        )

    schema = result["schema"]
    if not isinstance(schema, str):
        raise TypeError(f"{where}.schema must be a str")
    if schema != _REGION_DELTA_RANK_MULTI_SCHEMA:
        raise ValueError(
            f"{where}.schema must be {_REGION_DELTA_RANK_MULTI_SCHEMA!r}"
        )

    reference = result["reference"]
    if not isinstance(reference, str):
        raise TypeError(f"{where}.reference must be a str")
    if reference == "":
        raise ValueError(f"{where}.reference must be non-empty")

    scenarios = _validate_string_list(
        result["scenarios"], f"{where}.scenarios"
    )
    elements = _validate_string_list(
        result["elements"], f"{where}.elements"
    )
    regions = _validate_string_list(result["regions"], f"{where}.regions")

    if reference in scenarios:
        raise ValueError(
            f"{where}.reference must not appear in {where}.scenarios"
        )

    data = result["data"]
    if not isinstance(data, list):
        raise TypeError(f"{where}.data must be a list")
    n_scenarios = len(scenarios)
    n_elements = len(elements)
    n_regions = len(regions)
    if len(data) != n_scenarios * n_elements * n_regions:
        raise ValueError(
            f"{where}.data must contain exactly one row per "
            "(scenario, element, region) triple"
        )

    row_index = 0
    for scenario in scenarios:
        for element in elements:
            for region in regions:
                row_where = f"{where}.data[{row_index}]"
                row = data[row_index]
                if not isinstance(row, dict):
                    raise TypeError(f"{row_where} must be a dict")
                if tuple(row.keys()) != _REGION_DELTA_RANK_MULTI_ROW_KEYS:
                    raise ValueError(
                        f"{row_where} must have exactly the keys scenario, "
                        "element, region, state, rank, magnitude, "
                        "uncertainty in order"
                    )

                if not isinstance(row["scenario"], str):
                    raise TypeError(f"{row_where}.scenario must be a str")
                if row["scenario"] != scenario:
                    raise ValueError(
                        f"{row_where}.scenario must be {scenario!r} for its "
                        "position"
                    )
                if not isinstance(row["element"], str):
                    raise TypeError(f"{row_where}.element must be a str")
                if row["element"] != element:
                    raise ValueError(
                        f"{row_where}.element must be {element!r} for its "
                        "position"
                    )
                if not isinstance(row["region"], str):
                    raise TypeError(f"{row_where}.region must be a str")
                if row["region"] != region:
                    raise ValueError(
                        f"{row_where}.region must be {region!r} for its "
                        "position"
                    )

                state = row["state"]
                if not isinstance(state, str):
                    raise TypeError(f"{row_where}.state must be a str")
                if state not in _REGION_DELTA_RANK_MULTI_STATES:
                    raise ValueError(
                        f"{row_where}.state must be one of both, added, "
                        "dropped, missing"
                    )

                rank = row["rank"]
                magnitude = row["magnitude"]
                uncertainty = row["uncertainty"]
                if state == "both":
                    if not isinstance(rank, int) or isinstance(rank, bool):
                        raise TypeError(
                            f"{row_where}.rank must be a non-bool int"
                        )
                    _validate_number(
                        magnitude, f"{row_where}.magnitude", nullable=False
                    )
                    _validate_number(
                        uncertainty,
                        f"{row_where}.uncertainty",
                        nullable=False,
                    )
                    if uncertainty < 0:
                        raise ValueError(
                            f"{row_where}.uncertainty must be non-negative"
                        )
                else:
                    if rank is not None:
                        raise ValueError(
                            f"{row_where}.rank must be None when state is "
                            f"{state!r}"
                        )
                    if magnitude is not None or uncertainty is not None:
                        raise ValueError(
                            f"{row_where}.magnitude and uncertainty must be "
                            f"None when state is {state!r}"
                        )
                row_index += 1

    return reference, scenarios, elements, regions, data

def _validate_window_rank(
    result: Any, *, where: str = "result"
) -> tuple[list[str], list[str], list]:
    """Validate a complete :func:`window_rank` result.

    Returns the window names (in data order), the shared scenario order
    and, per window, the scenario means (floats or ``None``).
    """
    if not isinstance(result, dict):
        raise TypeError(f"{where} must be a dict")
    if tuple(result.keys()) != _REGION_WINDOW_RANK_RESULT_KEYS:
        raise ValueError(
            f"{where} must have exactly the keys schema, data in order"
        )

    schema = result["schema"]
    if not isinstance(schema, str):
        raise TypeError(f"{where}.schema must be a str")
    if schema != _REGION_WINDOW_RANK_SCHEMA:
        raise ValueError(
            f"{where}.schema must be {_REGION_WINDOW_RANK_SCHEMA!r}"
        )

    data = result["data"]
    if not isinstance(data, list):
        raise TypeError(f"{where}.data must be a list")
    if len(data) == 0:
        raise ValueError(f"{where}.data must be non-empty")

    for index, row in enumerate(data):
        row_where = f"{where}.data[{index}]"
        if not isinstance(row, dict):
            raise TypeError(f"{row_where} must be a dict")
        if tuple(row.keys()) != _REGION_WINDOW_RANK_ROW_KEYS:
            raise ValueError(
                f"{row_where} must have exactly the keys window, scenario, "
                "total, valid, missing_rate, mean, best, worst, stddev "
                "in order"
            )

        window = row["window"]
        if not isinstance(window, str):
            raise TypeError(f"{row_where}.window must be a str")
        if window == "":
            raise ValueError(f"{row_where}.window must be non-empty")
        scenario = row["scenario"]
        if not isinstance(scenario, str):
            raise TypeError(f"{row_where}.scenario must be a str")
        if scenario == "":
            raise ValueError(f"{row_where}.scenario must be non-empty")

        total = row["total"]
        if not isinstance(total, int) or isinstance(total, bool):
            raise TypeError(f"{row_where}.total must be a non-bool int")
        if total < 1:
            raise ValueError(f"{row_where}.total must be positive")
        valid = row["valid"]
        if not isinstance(valid, int) or isinstance(valid, bool):
            raise TypeError(f"{row_where}.valid must be a non-bool int")
        if valid < 0:
            raise ValueError(f"{row_where}.valid must be non-negative")
        if valid > total:
            raise ValueError(
                f"{row_where}.valid must not exceed {row_where}.total"
            )

        _validate_number(
            row["missing_rate"], f"{row_where}.missing_rate", nullable=False
        )
        if row["missing_rate"] != _round_output((total - valid) / total):
            raise ValueError(
                f"{row_where}.missing_rate must equal "
                "(total - valid) / total"
            )

        stat_fields = ("mean", "best", "worst", "stddev")
        _validate_number(row["mean"], f"{row_where}.mean", nullable=True)
        _validate_number(row["stddev"], f"{row_where}.stddev", nullable=True)
        for name in ("best", "worst"):
            value = row[name]
            if value is None:
                continue
            if not isinstance(value, int) or isinstance(value, bool):
                raise TypeError(f"{row_where}.{name} must be a non-bool int")
            if value < 1:
                raise ValueError(f"{row_where}.{name} must be positive")

        none_flags = [row[name] is None for name in stat_fields]
        if any(none_flags) and not all(none_flags):
            raise ValueError(
                f"{row_where}: mean, best, worst and stddev must be all "
                "None or all present"
            )
        if valid == 0 and not all(none_flags):
            raise ValueError(
                f"{row_where}: mean, best, worst and stddev must be None "
                "when valid is zero"
            )
        if not any(none_flags):
            if row["best"] > row["worst"]:
                raise ValueError(
                    f"{row_where}.best must not exceed {row_where}.worst"
                )
            if not (row["best"] <= row["mean"] <= row["worst"]):
                raise ValueError(
                    f"{row_where}.mean must lie between best and worst"
                )
            if row["stddev"] < 0:
                raise ValueError(f"{row_where}.stddev must be non-negative")

    windows: list[str] = []
    scenario_order: list[str] | None = None
    means: list[list] = []
    seen_windows: set[str] = set()
    index = 0
    n_rows = len(data)
    while index < n_rows:
        window = data[index]["window"]
        if window in seen_windows:
            raise ValueError(
                f"{where}.data rows for window {window!r} must form a "
                "single contiguous block"
            )
        seen_windows.add(window)
        block_scenarios = []
        block_means = []
        while index < n_rows and data[index]["window"] == window:
            block_scenarios.append(data[index]["scenario"])
            block_means.append(data[index]["mean"])
            index += 1
        if len(set(block_scenarios)) != len(block_scenarios):
            raise ValueError(
                f"{where}.data window {window!r} lists a scenario more "
                "than once"
            )
        if scenario_order is None:
            scenario_order = block_scenarios
        elif block_scenarios != scenario_order:
            raise ValueError(
                f"{where}.data window {window!r} must list the same "
                "scenarios in the same order as the first window"
            )
        windows.append(window)
        means.append(block_means)

    return windows, scenario_order, means

def _validate_region_interval_ranking(
    ranking: Any, *, where: str = "ranking"
) -> tuple[list[str], list[str], list, list, list]:
    """Validate a complete :func:`rank_region_intervals` result."""
    if not isinstance(ranking, dict):
        raise TypeError(f"{where} must be a dict")
    if tuple(ranking.keys()) != _REGION_REPORT_INTERVAL_RANK_RESULT_KEYS:
        raise ValueError(
            f"{where} must have exactly the keys schema, scenarios, elements, "
            "windows, regions, factors, pairs, data in order"
        )

    schema = ranking["schema"]
    if not isinstance(schema, str):
        raise TypeError(f"{where}.schema must be a str")
    if schema != _REGION_REPORT_INTERVAL_RANK_SCHEMA:
        raise ValueError(
            f"{where}.schema must be {_REGION_REPORT_INTERVAL_RANK_SCHEMA!r}"
        )

    scenarios = _validate_string_list(ranking["scenarios"], f"{where}.scenarios")
    elements = _validate_string_list(ranking["elements"], f"{where}.elements")

    windows = ranking["windows"]
    if not isinstance(windows, list):
        raise TypeError(f"{where}.windows must be a list")
    if len(windows) == 0:
        raise ValueError(f"{where}.windows must be non-empty")
    seen_windows: set[str] = set()
    for index, window in enumerate(windows):
        window_where = f"{where}.windows[{index}]"
        if not isinstance(window, dict):
            raise TypeError(f"{window_where} must be a dict")
        if list(window.keys()) != ["name", "start", "end"]:
            raise ValueError(
                f"{window_where} must have exactly the keys name, start, "
                "end in order"
            )
        window_name = window["name"]
        if not isinstance(window_name, str):
            raise TypeError(f"{window_where}.name must be a str")
        if window_name == "":
            raise ValueError(f"{window_where}.name must be non-empty")
        if window_name in seen_windows:
            raise ValueError(f"duplicate {where}.windows name: {window_name!r}")
        seen_windows.add(window_name)
        start_day = _parse_date(window["start"], f"{window_where}.start")
        end_day = _parse_date(window["end"], f"{window_where}.end")
        if start_day > end_day:
            raise ValueError(
                f"{window_where}.start must be on or before {window_where}.end"
            )

    regions = _validate_string_list(ranking["regions"], f"{where}.regions")

    factors = ranking["factors"]
    if not isinstance(factors, list):
        raise TypeError(f"{where}.factors must be a list")
    if len(factors) == 0:
        raise ValueError(f"{where}.factors must be non-empty")
    for index, factor in enumerate(factors):
        if not isinstance(factor, (int, float)) or isinstance(factor, bool):
            raise TypeError(
                f"{where}.factors[{index}] must be a finite non-bool int "
                "or float"
            )
        if not _is_finite(factor):
            raise ValueError(f"{where}.factors[{index}] must be finite")
        if factor <= 0:
            raise ValueError(f"{where}.factors[{index}] must be positive")
    for index in range(1, len(factors)):
        if factors[index] <= factors[index - 1]:
            raise ValueError(f"{where}.factors must be strictly increasing")

    pairs = ranking["pairs"]
    if not isinstance(pairs, list):
        raise TypeError(f"{where}.pairs must be a list")
    if len(pairs) == 0:
        raise ValueError(f"{where}.pairs must be non-empty")
    seen_pairs: set[str] = set()
    for index, pair in enumerate(pairs):
        pair_where = f"{where}.pairs[{index}]"
        if not isinstance(pair, dict):
            raise TypeError(f"{pair_where} must be a dict")
        if list(pair.keys()) != ["name", "left", "right"]:
            raise ValueError(
                f"{pair_where} must have exactly the keys name, left, right "
                "in order"
            )
        pair_name = pair["name"]
        left = pair["left"]
        right = pair["right"]
